import unittest

from seq import count_to


class TestSeq(unittest.TestCase):
    def test_counts(self):
        self.assertEqual(count_to(5), [1, 2, 3, 4, 5])
        self.assertEqual(count_to(1), [1])
        self.assertEqual(count_to(0), [])


if __name__ == '__main__':
    unittest.main()
